public <T> T inTransaction(SqlFunction<Connection, T> work) throws SQLException {
    try (Connection c = ds.getConnection()) {
        c.setAutoCommit(false);
        try {
            T r = work.apply(c);
            c.commit();
            return r;
        }
        catch (Exception e) {
            c.rollback();
            throw e;
        }
        finally { c.setAutoCommit(true); }
    }
}

